import networkx as nx
G = nx.Graph()
G.add_nodes_from(range(18))
G.add_edges_from([(2,9), (0,10), (15,17), (12,15), (2,6), (3,17), (0,14), (11,13), (9,14), (6,12), (10,13), (1,10), (11,17), (10,16), (1,5), (6,14), (5,10), (1,9), (4,14), (15,16), (3,12), (13,16), (2,3), (10,15), (7,13), (6,16), (2,8), (3,10), (0,15), (2,16)])
while min(nx.vertex_connectivity(G, u, v) for u in G.nodes for v in G.nodes if u < v) < 4:
    for u in G.nodes:
        for v in G.nodes:
            if u < v and not G.has_edge(u, v):
                G.add_edge(u, v)
                if min(nx.vertex_connectivity(G, u, v) for u in G.nodes for v in G.nodes if u < v) >= 4:
                    break
        else:
            continue
        break
print(list(G.edges))
